const { chromium } = require("playwright");
const path = require("path");

async function runAxe(page, label) {
  await page.addScriptTag({ path: "/tmp/axe.min.js" });
  const r = await page.evaluate(async () => await window.axe.run());
  const wcag = r.violations.filter(v => !v.tags.includes("best-practice"));
  const bp   = r.violations.filter(v =>  v.tags.includes("best-practice"));
  console.log(`\n=== ${label} ===`);
  console.log(`WCAG violations: ${wcag.length}, Best-practice: ${bp.length}`);
  if (wcag.length) console.log(JSON.stringify(wcag.map(v => ({ id: v.id, impact: v.impact,
    nodes: v.nodes.map(n => n.target) })), null, 2));
  if (bp.length)   console.log("BP:", bp.map(v => v.id));
  return wcag.length;
}

(async () => {
  const browser = await chromium.launch();
  let total = 0;

  // State 1: initial load
  {
    const page = await browser.newPage();
    await page.goto("file://" + path.resolve("index.html"), { waitUntil: "networkidle" });
    total += await runAxe(page, "Initial load");
    await page.close();
  }

  // State 2: submit with no selection (error state)
  {
    const page = await browser.newPage();
    await page.goto("file://" + path.resolve("index.html"), { waitUntil: "networkidle" });
    await page.click("button[type=submit]");
    await page.waitForTimeout(200);
    total += await runAxe(page, "Error state (no selection)");
    await page.close();
  }

  // State 3: submit with a selection (success state)
  {
    const page = await browser.newPage();
    await page.goto("file://" + path.resolve("index.html"), { waitUntil: "networkidle" });
    await page.click("#notif-email");
    await page.click("button[type=submit]");
    await page.waitForTimeout(200);
    total += await runAxe(page, "Success state (email selected)");
    await page.close();
  }

  await browser.close();
  console.log(`\nTotal WCAG violations across all states: ${total}`);
  process.exit(total > 0 ? 1 : 0);
})();
