// with no pointer-event tricks needed — the input stays fully reachable.
function RadioOption({ id, name, value, labelText }) {
  // The outer element IS the label, making the whole row the click target.
  const wrapper = document.createElement("label");
  wrapper.className = "radio-option";
  wrapper.htmlFor = id;

  const input = document.createElement("input");
  input.type = "radio";
  input.id = id;
  input.name = name;
  input.value = value;
