// Renders a single radio option as a wrapping <label> row.
// Using a wrapping <label> means the entire row is the native click/tap target
// with no pointer-event tricks needed — the input stays fully reachable.
function RadioOption({ id, name, value, labelText }) {
  // The outer element IS the label, making the whole row the click target.
  const wrapper = document.createElement("label");
  wrapper.className = "radio-option";
  wrapper.htmlFor = id;

  const input = document.createElement("input");
  input.type = "radio";
  input.id = id;
  input.name = name;
  input.value = value;
  input.required = true;

  const span = document.createElement("span");
  span.className = "radio-option__text";
  span.textContent = labelText;

  // Keep the selected class in sync with the checked state for styling.
  input.addEventListener("change", () => {
    // Remove is-selected from all sibling options in the same group.
    document
      .querySelectorAll(`input[name="${name}"]`)
      .forEach((el) => el.closest(".radio-option").classList.remove("is-selected"));
    if (input.checked) {
      wrapper.classList.add("is-selected");
    }
  });

  wrapper.appendChild(input);
  wrapper.appendChild(span);
  return wrapper;
}

// ─── Component: RadioGroup ──────────────────────────────────────────────────
// Wraps a set of RadioOption components in an accessible <fieldset>/<legend>.
function RadioGroup({ legendText, name, options, required = false }) {
  const fieldset = document.createElement("fieldset");

  const legend = document.createElement("legend");
  if (required) {
    legend.innerHTML = `${legendText} <span class="required-mark" aria-hidden="true">*</span>`;
  } else {
    legend.textContent = legendText;
  }
  fieldset.appendChild(legend);

  const optionList = document.createElement("div");
  optionList.className = "radio-options";

  options.forEach((opt) => {
    optionList.appendChild(RadioOption({ ...opt, name }));
  });

  fieldset.appendChild(optionList);
  return fieldset;
}

// ─── Component: NotificationForm ────────────────────────────────────────────
// A form section with the notification-preference radio group and a submit
// button. Handles validation and announces results via an aria-live region.
function NotificationForm() {
  const section = document.createElement("section");
  section.className = "form-section";
  section.setAttribute("aria-labelledby", "form-section-title");

  // Section heading
  const sectionHeader = document.createElement("div");
  sectionHeader.className = "form-section-header";

  const heading = document.createElement("h2");
  heading.id = "form-section-title";
  heading.textContent = "Notification Preferences";

  const subheading = document.createElement("p");
  subheading.textContent = "Choose how you would like us to reach you.";

  sectionHeader.appendChild(heading);
  sectionHeader.appendChild(subheading);
  section.appendChild(sectionHeader);

  // Form
  const form = document.createElement("form");
  form.noValidate = true;

  // Required-fields legend note
  const requiredNote = document.createElement("p");
  requiredNote.className = "required-note";
  requiredNote.innerHTML =
    'Fields marked with <span aria-hidden="true">*</span> are required.';
  form.appendChild(requiredNote);

  // Live region – announces success after submission
  const statusMsg = document.createElement("div");
  statusMsg.id = "form-status";
  statusMsg.setAttribute("role", "status");
  statusMsg.setAttribute("aria-live", "polite");
  statusMsg.setAttribute("aria-atomic", "true");
  statusMsg.className = "status-message";
  form.appendChild(statusMsg);

  // Error message – announced assertively on invalid submit
  const errorMsg = document.createElement("p");
  errorMsg.id = "form-error";
  errorMsg.className = "error-message";
  errorMsg.setAttribute("aria-live", "assertive");
  errorMsg.setAttribute("aria-atomic", "true");
  errorMsg.hidden = true;
  form.appendChild(errorMsg);

  // form-field div (required by task spec)
  const formField = document.createElement("div");
  formField.className = "form-field";

  formField.appendChild(
    RadioGroup({
      legendText: "How do you prefer to receive notifications?",
      name: "notification-preference",
      required: true,
      options: [
        { id: "notif-email", value: "email",  labelText: "Email" },
        { id: "notif-sms",   value: "sms",    labelText: "SMS" },
        { id: "notif-push",  value: "push",   labelText: "Push Notifications" },
      ],
    })
  );

  form.appendChild(formField);

  // Submit button
  const submitBtn = document.createElement("button");
  submitBtn.type = "submit";
  submitBtn.className = "btn-submit";
  submitBtn.textContent = "Save preferences";
  form.appendChild(submitBtn);

  // ── Submit handler ──────────────────────────────────────────────────────
  form.addEventListener("submit", (event) => {
    event.preventDefault();

    const selected = form.querySelector(
      'input[name="notification-preference"]:checked'
    );

    // Clear previous status
    statusMsg.textContent = "";

    if (!selected) {
      errorMsg.textContent =
        "Error: Please select a notification preference before saving.";
      errorMsg.hidden = false;
      // Move focus to the first radio so keyboard users know where to act.
      form.querySelector('input[name="notification-preference"]').focus();
      return;
    }

    errorMsg.hidden = true;
    errorMsg.textContent = "";

    const labels = {
      email: "Email",
      sms:   "SMS",
      push:  "Push Notifications",
    };

    statusMsg.textContent = `Preferences saved! You'll receive notifications via ${
      labels[selected.value]
    }.`;
  });

  section.appendChild(form);
  return section;
}

// ─── Component: App ─────────────────────────────────────────────────────────
function App() {
  const container = document.createElement("div");
  container.className = "app-container";
  container.appendChild(NotificationForm());
  return container;
}

// ─── Mount ──────────────────────────────────────────────────────────────────
document.addEventListener("DOMContentLoaded", () => {
  document.getElementById("root").appendChild(App());
});
