*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* ─── Tokens ────────────────────────────────────────────────────────────── */
:root {
  --bg-page:        #080a12;
  --bg-card:        #0f1221;
  --bg-card-hover:  #141729;
  --bg-option-hover: rgba(99, 102, 241, 0.08);
  --bg-option-selected: rgba(99, 102, 241, 0.12);

  --border-subtle:  #1e2340;
  --border-muted:   #2e3256;
  --border-accent:  #6366f1;

  --text-primary:   #e2e8f0;
  --text-muted:     #8b92b0;
  --text-legend:    #c4cadf;

  --accent:         #6366f1;
  --accent-light:   #818cf8;
  --accent-dark:    #4f46e5;
  --accent-darker:  #4338ca;

  --error:          #f87171;
  --success:        #34d399;

  --radius-card:    12px;
  --radius-option:  8px;
  --radius-btn:     8px;

  --shadow-card:    0 4px 24px rgba(0, 0, 0, 0.5);
  --shadow-btn:     0 2px 12px rgba(79, 70, 229, 0.35);
}

/* ─── Skip link ─────────────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: 0.5rem 1rem;
  background: var(--accent);
  color: #fff;
  border-radius: 0 0 var(--radius-btn) var(--radius-btn);
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
  transition: top 0.15s;
}
.skip-link:focus {
  top: 0;
}

/* ─── Body / page ───────────────────────────────────────────────────────── */
body {
  background-color: var(--bg-page);
  color: var(--text-primary);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100dvh;
}

.page-container {
  max-width: 560px;
  margin: 0 auto;
  padding: 3rem 1.25rem 4rem;
}

/* ─── Page header ───────────────────────────────────────────────────────── */
.page-header {
  margin-bottom: 2.5rem;
}

.page-header h1 {
  font-size: clamp(1.5rem, 4vw, 2rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text-primary);
}

.page-subtitle {
  margin-top: 0.375rem;
  color: var(--text-muted);
  font-size: 0.9375rem;
}

/* ─── Form section card ─────────────────────────────────────────────────── */
.form-section {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-card);
  box-shadow: var(--shadow-card);
  overflow: hidden;
}

.form-section-header {
  padding: 1.5rem 1.5rem 0;
}

.form-section-header h2 {
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--text-primary);
  letter-spacing: -0.01em;
}

.form-section-header p {
  margin-top: 0.25rem;
  font-size: 0.875rem;
  color: var(--text-muted);
}

/* ─── Form ──────────────────────────────────────────────────────────────── */
form {
  padding: 1.25rem 1.5rem 1.5rem;
}

.required-note {
  font-size: 0.8125rem;
  color: var(--text-muted);
  margin-bottom: 1.25rem;
}

/* ─── form-field wrapper ────────────────────────────────────────────────── */
.form-field {
  margin-bottom: 1.75rem;
}

/* ─── Fieldset / legend ─────────────────────────────────────────────────── */
fieldset {
  border: none;
  padding: 0;
}

legend {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text-legend);
  margin-bottom: 1rem;
  float: left;
  width: 100%;
}

/* Clear float so options flow below the legend */
fieldset::after {
  content: "";
  display: table;
  clear: both;
}

.required-mark {
  color: var(--error);
  margin-left: 0.125rem;
}

/* ─── Radio options list ────────────────────────────────────────────────── */
.radio-options {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

/* ─── Single radio option ───────────────────────────────────────────────── */
.radio-option {
  display: flex;
  align-items: center;
  gap: 0.875rem;
  padding: 0.875rem 1rem;
  border: 1px solid var(--border-muted);
  border-radius: var(--radius-option);
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
  position: relative;
}

.radio-option:hover {
  background: var(--bg-option-hover);
  border-color: var(--accent);
}

.radio-option.is-selected {
  background: var(--bg-option-selected);
  border-color: var(--accent);
}

/* ─── Native radio input (custom-styled) ───────────────────────────────── */
.radio-option input[type="radio"] {
  appearance: none;
  -webkit-appearance: none;
  flex-shrink: 0;
  width: 1.125rem;
  height: 1.125rem;
  border: 2px solid var(--border-muted);
  border-radius: 50%;
  cursor: pointer;
  background: transparent;
  position: relative;
  transition: border-color 0.15s, background 0.15s;
}

/* Inner dot via ::before */
.radio-option input[type="radio"]::before {
  content: "";
  display: block;
  width: 0.4375rem;
  height: 0.4375rem;
  background: #fff;
  border-radius: 50%;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) scale(0);
  transition: transform 0.15s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.radio-option input[type="radio"]:checked {
  border-color: var(--accent);
  background: var(--accent);
}

.radio-option input[type="radio"]:checked::before {
  transform: translate(-50%, -50%) scale(1);
}

/* Focus ring — visible only for keyboard navigation */
.radio-option input[type="radio"]:focus-visible {
  outline: 3px solid var(--accent-light);
  outline-offset: 3px;
}

/* ─── Radio option label text ───────────────────────────────────────────── */
.radio-option__text {
  font-size: 0.9375rem;
  color: var(--text-primary);
  flex: 1;
  /* The wrapping <label> already makes the full row the click target. */
}

/* ─── Error message ─────────────────────────────────────────────────────── */
.error-message {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.875rem;
  color: var(--error);
  background: rgba(248, 113, 113, 0.08);
  border: 1px solid rgba(248, 113, 113, 0.25);
  border-radius: 6px;
  padding: 0.625rem 0.875rem;
  margin-bottom: 1.25rem;
}

.error-message:empty,
.error-message[hidden] {
  display: none;
}

/* ─── Submit button ─────────────────────────────────────────────────────── */
.btn-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  padding: 0.8125rem 1.5rem;
  background: var(--accent-dark);
  color: #fff;
  font-size: 0.9375rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-btn);
  cursor: pointer;
  box-shadow: var(--shadow-btn);
  transition: background 0.15s, box-shadow 0.15s, transform 0.1s;
}

.btn-submit:hover {
  background: var(--accent-darker);
  box-shadow: 0 4px 16px rgba(79, 70, 229, 0.45);
}

.btn-submit:active {
  transform: translateY(1px);
}

.btn-submit:focus-visible {
  outline: 3px solid var(--accent-light);
  outline-offset: 3px;
}

/* ─── Status / success message ──────────────────────────────────────────── */
.status-message {
  font-size: 0.875rem;
  color: var(--success);
