.radio-option input[type="radio"] {
  appearance: none;
  -webkit-appearance: none;
  flex-shrink: 0;
  width: 1.125rem;
  height: 1.125rem;
  border: 2px solid var(--border-muted);
  border-radius: 50%;
  cursor: pointer;
  background: transparent;
  position: relative;
  transition: border-color 0.15s, background 0.15s;
